const rules={chess:'<h3>Шахматы</h3><p>Белые ходят первыми. Выберите свою фигуру и подсвеченное поле. Король не может оставаться под шахом. Реализованы рокировки, взятие на проходе и выбор фигуры при превращении пешки.</p><p>Мат завершает партию победой. Пат и недостаток материала — ничья. После трёх повторений позиции или 50 ходов каждой стороны без взятий и движения пешек доступна кнопка «Заявить ничью». Пять повторений или 75 ходов завершают партию автоматически.</p><p>Историю партии можно скачать в PGN. У каждого игрока отдельный запас времени на партию. В режимах с добавлением секунды начисляются после сделанного хода. Истечение времени означает поражение. Тренировка проходит без часов. Если соперник не имеет материала для мата, при истечении времени засчитывается ничья.</p><p><a href="https://handbook.fide.com/chapter/e012023" target="_blank" rel="noopener">Правила FIDE</a>. Физические требования к турнирам (касание фигуры, запись на бланке) к интерфейсу не применяются.</p>',short:'<h3>Короткие нарды</h3><p>У каждого 15 шашек. Двигайтесь в противоположных направлениях, соберите все шашки в своём доме и выведите их. Для первого хода бросается по одной кости: больший результат определяет игрока, оба значения используются для его первого хода. При равенстве бросок повторяется.</p><p>Каждое число — отдельное перемещение. Дубль даёт четыре перемещения. Вы обязаны использовать максимум доступных костей. Если можно использовать только одну из двух — используется большее число, когда оно доступно.</p><p>На пункт с двумя и более шашками соперника идти нельзя. Одиночная шашка соперника сбивается на бар. Пока есть шашки на баре, сначала введите их в дом соперника. Подсветка показывает только законные продолжения.</p><p>Вывод доступен, когда все ваши шашки в доме. Большее число позволяет вывести с самого дальнего занятого пункта, если дальше шашек нет.</p><p><a href="https://usbgf.org/wp-content/uploads/2022/11/Beginners-Guide-to-Backgammon.pdf" target="_blank" rel="noopener">Правила коротких нард · USBGF</a>.</p>',long:'<h3>Длинные нарды</h3><p>Все 15 шашек начинают на голове. Оба игрока движутся в одном направлении; дом — последние 6 пунктов личного маршрута. Шашки не сбиваются, и на любой пункт соперника идти нельзя.</p><p>С головы снимается одна шашка за ход. При первом ходе игрока с дублем 3–3, 4–4 или 6–6 разрешается снять две. Первый ход определяется разными стартовыми костями, поэтому исключение на первом дубле относится к игроку, который ещё не ходил.</p><p>Нельзя выстроить шесть занятых пунктов подряд, запирающих все шашки соперника, даже промежуточным перемещением. Все кости по возможности разыгрываются; дубль — четыре перемещения.</p><p>Сначала соберите все шашки в доме, затем выводите их по точному числу; если более дальних шашек нет, разрешён вывод с ближайшего занятого пункта по большему числу.</p><p>Первый бросок и максимальное использование костей устроены так же, как в коротких нардах.</p>'};
function openRules(){setText('rulesText','');$('rulesText').innerHTML=rules[state?.discipline||kind]+'<h3>Матч Two Aces</h3><p>Одна партия или серия до 3 побед. Победа в партии даёт одну победу в серии; куб удвоения и множители «марс» здесь не применяются. Онлайн-ходы и случайные кости проверяются сервером. Компьютер и тренировка не влияют на рейтинг. Сдаться и предложить ничью можно через верхнее меню; соперник должен подтвердить ничью. На каждую партию доступно одно предложение ничьей от каждого игрока.</p><p>Нарды доступны зарегистрированным игрокам, включая приглашения и просмотр. Рейтинг и история ведутся отдельно для шахмат, коротких и длинных нард.</p>';$('rules').showModal();}
for(const b of document.querySelectorAll('[data-rules]'))b.onclick=openRules;for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>b.closest('dialog').close();
function localDice(){const a=new Uint32Array(2);for(let i=0;i<2;i++){do{crypto.getRandomValues(a.subarray(i,i+1));}while(a[i]>=4294967292);}return Array.from(a,n=>n%6+1);}
async function localStart(nextMode){if(!await ensureGameParticipation())return;stop();mode=nextMode;player=$('side').value==='random'?localDice()[0]%2:Number($('side').value);flipped=player===1;state=createGame(kind);series=createMatch(Number($('raceTo').value));profiles=mode==='training'?['Белые','Чёрные']:player===0?['Вы','Компьютер']:['Компьютер','Вы'];ready=true;resetLocalClock();$('lobby').hidden=true;$('game').hidden=false;render();scheduleBot();}
async function launchOnline(action,challenge=false,stake=0){if(!await ensureGameParticipation())return;stop();chosenStake=stake;const gen=generation;busy=true;try{const d=await request({action,...settings(),...(challenge?{challenge:true}:{}),...(stake?{stake,requestId:createRequest()}:{})});if(gen!==generation)return;mode='online';adopt(d);if(challenge){try{await request({action:'challenge',roomId});if(gen===generation)setText('waitingNote','Вызов отправлен в чат игроков');}catch(e){if(gen===generation)setText('waitingNote',e.message);}}if(gen===generation)schedulePoll();}catch(e){if(gen===generation)error(e.message);}finally{paintPendingCreate();if(gen===generation){busy=false;if(state){renderBoard();renderControls();}}}}
replayUI=mountReplayOffers({after:gameWager,context:()=>({roomId,wager,state,mode,spectator,player,clockOffset}),request,update:d=>{adopt(d);schedulePoll(0);},confirm:confirmAction,error,openRoom:async(code,previous)=>{if(roomId!==previous||mode!=='online'||spectator)return;stop();const gen=generation;busy=true;try{const data=await request({action:'join',roomId:code});if(gen!==generation)return;mode='online';adopt(data);schedulePoll();}finally{if(gen===generation){busy=false;render();}}}});
const boardLobby=mountBoardLobby({getKind:()=>kind,back:exit,join,launch:async(type,stake)=>{if(busy)return;if(['solo','training'].includes(type))await localStart(type);else await launchOnline(type==='find'?'matchmake':'create',type==='challenge',['friend','challenge'].includes(type)?stake:0);}});
function adopt(d){connectionNotice.update(d.connection,d.player);if(d.roomId===roomId&&optimisticRevision!==null){if(d.revision<=optimisticRevision)return;optimisticRevision=null;}if(d.roomId===roomId&&d.revision<revision)return;if(d.cancelled){stop();clearCreateRequest();error('Игра отменена. Ставки возвращены на баланс Poker21.');return;}wager=d.wager||null;paintWager();if(wager)clearCreateRequest();if(d.roomId===roomId&&d.revision<revision)return;onlineTurnSeconds=d.turnSeconds||60;timeControl=d.timeControl||null;clockRemaining=d.clockRemaining||null;const prior=state,changed=revision!==d.revision;roomId=d.roomId;revision=d.revision;player=d.player;spectator=d.spectator===true;ready=d.ready;deadline=d.turnDeadline;state=d.state;series=d.match;kind=state.discipline;if(d.equipment){const key=JSON.stringify(d.equipment);roomEquipment=d.equipment;if(key!==roomEquipmentKey){roomEquipmentKey=key;applyEquipment(roomEquipment,false,false);}}profiles=d.playerProfiles.map((p,i)=>p?.name||'Ждём соперника');if(!prior)flipped=player===1;$('lobby').hidden=true;$('waiting').hidden=ready||spectator;$('game').hidden=!ready&&!spectator;setText('roomCode',roomId);$('inviteLink').value=inviteURL();setText('waitingNote',d.searching?'Ищем игрока с такой же дисциплиной. Поиск активен 2 минуты. Можно также передать ссылку другу.':'Передайте ссылку другу или код комнаты.');if(changed){selected=null;render(d.transition);}}
function inviteURL(watch=false){return 'https://t.me/Poker_dvatuza_bot/DvaTuza?startapp=board_'+(watch?'watch_':'')+roomId;}
function schedulePoll(delay=650){clearTimeout(pollTimer);const gen=generation,paidPoll=wager?.status==='paid';pollTimer=setTimeout(async()=>{try{const d=await request({action:spectator?'watch':'room',roomId,sinceRevision:revision});if(gen!==generation)return;if(d.roomId===roomId&&(d.revision<revision||optimisticRevision!==null&&d.revision<=optimisticRevision)){schedulePoll();return;}errorCount=0;error('');if(d.unchanged){connectionNotice.update(d.connection,player);deadline=d.turnDeadline;if(d.wager){const changed=JSON.stringify(wager)!==JSON.stringify(d.wager);wager=d.wager;if(changed){paintWager();render();}}replayUI?.render();}else adopt(d);}catch(e){if(gen!==generation||wager?.status==='paid'&&!paidPoll)return;errorCount++;error(e.message+(e.status===404?' · выйдите и создайте новую комнату.':' · переподключаемся…'));if([401,403,404].includes(e.status))return;}if(gen===generation)schedulePoll(document.hidden?8000:wager&&['paid','refunded'].includes(wager.status)?2000:Math.min(5000,650+errorCount*500));},delay);}
async function join(code,watch=false){if(!watch&&!await ensureGameParticipation())return;code=String(code).trim().toUpperCase();if(!/^[A-HJ-NP-Z2-9]{10}$/.test(code)){error('Введите код из 10 символов.');return;}const gen=generation;try{const info=await request({action:'preview',roomId:code});if(gen!==generation)return;if(info.full&&!watch)throw Error('Место соперника уже занято.');const enter=async()=>{stop();const ownGen=generation;busy=true;try{const d=await request({action:watch?'watch':'join',roomId:code});if(ownGen!==generation)return;mode='online';adopt(d);schedulePoll();}catch(e){if(ownGen===generation)error(e.message);}finally{if(ownGen===generation){busy=false;if(state){renderBoard();renderControls();}}}};if(watch)await enter();else confirmAction(info.wager?'Игра на '+info.wager.stake+' фишек':'Приглашение: '+labels[info.discipline],(info.wager?'Вы согласны сыграть? ':'')+info.caller+' приглашает сыграть. '+(info.timeControl?info.timeControl.label:info.turnSeconds+' сек. на ход')+' · '+(info.raceTo===3?'до 3 побед':'одна партия')+'.'+(info.wager?' Ставка каждого — '+info.wager.stake+' фишек. Банк — '+info.wager.bank+', комиссия 10%, победителю — '+info.wager.payout+'. При подтверждении ставка спишется с Poker21.':' Вход 0.'),info.wager?'Согласен, играть':'Принять',enter);}catch(e){if(gen===generation)error(e.message);}}
$('join').onclick=()=>join($('roomInput').value);$('roomInput').onkeydown=e=>{if(e.key==='Enter')$('join').click();};
$('copyInvite').onclick=async()=>{try{await navigator.clipboard.writeText(inviteURL());setText('waitingNote','Ссылка скопирована');}catch{$('inviteLink').select();setText('waitingNote','Скопируйте выделенную ссылку');}};
$('shareInvite').onclick=async()=>{try{if(navigator.share)await navigator.share({title:labels[kind]+' · Two Aces',text:'Приглашаю сыграть в '+labels[kind].toLowerCase(),url:inviteURL()});else $('copyInvite').click();}catch{}};
$('cancelWaiting').onclick=async()=>{if(busy)return;busy=true;try{await request({action:'cancel',roomId});stop();}catch(e){busy=false;setText('waitingNote',e.message);schedulePoll(0);}};
async function send(m){if(boardDice.busy&&['roll','move','undo-step'].includes(m.type))return false;if(!state||state.winner!==null&&!(m.type==='resign'&&wager?.status==='playing')||spectator||busy||!ready)return false;if(m.type==='undo-step')settleMoveAnimation();if(mode==='online'){busy=true;clearTimeout(pollTimer);const gen=generation,baseRevision=revision,confirmed=structuredClone(state);if(kind!=='chess'&&m.type==='move'){const predicted=structuredClone(state);if(action(predicted,player,m)){optimisticRevision=baseRevision;state=predicted;selected=null;renderBoard({lastMove:state.lastMove,revision:baseRevision+1});}}renderControls();try{const d=await request({action:'move',roomId,revision:baseRevision,move:m});if(gen!==generation)return false;adopt(d);return true;}catch(e){if(gen===generation){if(optimisticRevision===baseRevision&&revision===baseRevision){state=confirmed;optimisticRevision=null;render();}error(e.message);}return false;}finally{if(gen===generation){busy=false;renderBoard();renderControls();schedulePoll(0);}}}
 renderClock();if(state.winner!==null)return false;const before=structuredClone(state),dice=m.type==='roll'?localDice():undefined,who=mode==='training'?state.turn:player;if(!action(state,who,m,dice))return false;
 if(m.type==='undo-step')checkpoint=null;if(mode==='training'&&['move','roll'].includes(m.type))checkpoint={before,beforeSeries:structuredClone(series),move:{...m},dice};if(mode==='solo'&&m.type==='draw-offer')action(state,1-player,{type:'draw-accept'});afterLocal(before);return true;}
function resetLocalClock(){timeControl=kind==='chess'?TC.find($('chessTime').value):null;clockRemaining=timeControl?TC.resetClock(timeControl):null;deadline=mode==='training'?null:timeControl?(timeControl.seconds?Date.now()+timeControl.seconds*1000:null):Date.now()+turnLimitSeconds(state,Number($('turnSeconds').value))*1000;}
function settleLocalClock(before){if(timeControl){if(deadline)deadline=TC.advanceClock(clockRemaining,deadline,before.turn,timeControl,Date.now());}else deadline=Date.now()+turnLimitSeconds(state,Number($('turnSeconds').value))*1000;}
function afterLocal(before){selected=null;if(mode!=='training'&&state.winner===null&&(state.turn!==before.turn||state.phase==='moving'&&before.phase!==state.phase))settleLocalClock(before);if(state.winner!==null){recordWin(series,state.winner);deadline=null;}render(state.lastMove!==before.lastMove?{lastMove:state.lastMove}:null);scheduleBot();}
function scheduleBot(){clearTimeout(botTimer);if(boardDice.busy||mode!=='solo'||!state||state.winner!==null||state.turn===player||botPending)return;const gen=generation;botTimer=setTimeout(()=>{if(gen!==generation||mode!=='solo'||state.turn===player)return;if(!bot){bot=new Worker(gameWorkerURL('./app-board-games-worker.js'));bot.onmessage=({data})=>{if(data.id!==botJob||gen!==generation||mode!=='solo')return;botPending=false;renderClock();if(state.winner!==null)return;if(!data.move){error('Компьютер не смог выбрать ход. Попробуйте новую партию.');return;}const before=structuredClone(state);if(action(state,1-player,data.move,data.move.type==='roll'?localDice():undefined))afterLocal(before);};bot.onerror=()=>{botPending=false;error('Не удалось загрузить компьютер. Попробуйте открыть игру снова.');};}botPending=true;bot.postMessage({id:++botJob,state,level:$('difficulty').value});},state.discipline==='chess'?450:300);}
function canMove(){return state&&ready&&!spectator&&!busy&&!boardDice.busy&&state.winner===null&&(mode==='training'||state.turn===player);}
function render(transition){if(!state)return;renderPlayers();$('chessBoard').hidden=kind!=='chess';$('nardsBoard').hidden=kind==='chess';$('nardsFrame').hidden=kind==='chess';renderControls(true);renderBoard(transition);renderClock();const finished=state.winner!==null;$('result').hidden=!finished;if(finished){const h=$('result').querySelector('h2'),p=$('result').querySelector('p');h.textContent=state.winner==='draw'?'Ничья':profiles[state.winner]+' — победа';p.textContent=({checkmate:'Мат',stalemate:'Пат',material:'Недостаточно материала',resign:spectator?profiles[1-state.winner]+' сдался':state.winner===player?'Соперник сдался':'Вы сдались',timeout:'Время вышло','timeout-material':'Время вышло: у соперника нет материала для мата',agreement:'Ничья по соглашению',claim:'Ничья по заявлению',repetition:'Пятикратное повторение','75-moves':'75 ходов без взятий и движения пешек','borne-off':'Все 15 шашек выведены'}[state.endReason]||'Партия завершена')+(series.winner!==null?' · серия завершена':'');$('again').hidden=spectator||mode==='online'&&player!==0||!!(wager&&wager.status!=='playing');$('again').textContent=series.winner!==null?'Новый матч':series.target===3?'Следующая партия':'Новая партия';}showResultSummary(finished);checkDrawOffer();}
function showResultSummary(finished){
 const dialog=$('resultSummary');
 if(!finished){if(dialog.open)dialog.close();return;}
 const key=JSON.stringify([roomId,series.number,series.round,state.winner,state.endReason]);
 dialog.querySelector('h2').textContent=$('result').querySelector('h2').textContent;
 dialog.querySelector('p').textContent=$('result').querySelector('p').textContent;
 if(key!==resultSummaryKey){resultSummaryKey=key;if(!dialog.open)dialog.showModal();}
}
function renderPlayers(){const clockParent=kind==='chess'?document.querySelector('#game .turn-line'):$('boardClock');if($('clock').parentElement!==clockParent){if(kind==='chess')clockParent.append($('clock'));else clockParent.prepend($('clock'));}const statusParent=kind==='chess'?document.querySelector('#game .turn-line'):$('boardClock');if($('turnText').parentElement!==statusParent)statusParent.append($('turnText'));setText('series',(spectator?'Просмотр · ':'')+labels[kind]+' · '+(series.target===3?'До 3 побед · '+series.wins.join(' : ')+' · партия '+series.round:'Одна партия'));for(const card of $('matchup').querySelectorAll('[data-player]')){const i=Number(card.dataset.player),name=profiles[i];card.classList.toggle('active',state.winner===null&&state.turn===i);card.classList.toggle('my-turn',state.winner===null&&ready&&!spectator&&mode!=='training'&&i===player&&state.turn===i);card.querySelector('strong').textContent=name;card.querySelector('i').textContent=Array.from(name)[0]||'?';card.querySelector('small').textContent=(!spectator&&mode!=='training'&&i===player?'Вы · ':'')+(i===0?'Белые':'Чёрные')+(state.winner===null&&state.turn===i?(!spectator&&mode!=='training'&&i===player?' · Ваш ход':' · ходит'):'');}}
function renderClock(){if(!state||!mode)return;const mine=state.winner===null&&ready&&!spectator&&(mode==='training'||state.turn===player);if($('turnText').dataset.mine!==String(mine))$('turnText').dataset.mine=String(mine);setText('turnText',state.winner!==null?'Партия завершена':!ready?'Ждём соперника':spectator?'Ход: '+profiles[state.turn]:mine?'Ваш ход':'Ход: '+profiles[state.turn]);const clockHidden=!deadline||state.winner!==null||!ready;if($('clock').hidden!==clockHidden)$('clock').hidden=clockHidden;clockWarning.update({seconds:deadline?Math.max(0,Math.ceil((deadline-(Date.now()+(mode==='online'?clockOffset:0)))/1000)):null,active:!clockHidden,sound:mine,key:[roomId,series.number,series.round,state.ply,state.turn].join(':')});if(deadline&&state.winner===null&&ready){const left=Math.max(0,Math.ceil((deadline-(Date.now()+(mode==='online'?clockOffset:0)))/1000));if(timeControl){const values=clockRemaining.map((v,i)=>i===state.turn?left:Math.ceil(v/1000));const fmt=v=>Math.floor(v/60)+':'+String(v%60).padStart(2,'0');setText('clock','Белые '+fmt(values[0])+' · Чёрные '+fmt(values[1])+' · '+timeControl.label);}else setText('clock',left+' с · лимит '+turnLimitSeconds(state,mode==='online'?onlineTurnSeconds:Number($('turnSeconds').value))+' с');if(left===0&&mode==='solo'){expireTurn(state);recordWin(series,state.winner);deadline=null;render();}}}
