function chooseMove(moves,callback){if(moves.length===1){callback(moves[0]);return;}const d=$('promotion');d.querySelector('h2').textContent=kind==='chess'?'Превращение пешки':'Выберите кость';d.querySelector('p').textContent=kind==='chess'?'Во что превратить пешку?':'Оба значения позволяют это перемещение';const box=d.querySelector('div');box.replaceChildren();for(const move of moves){const b=document.createElement('button');if(kind==='chess'){b.innerHTML=pieceSVG(move.promotion,state.turn===0?'w':'b',equipment.pieces);b.setAttribute('aria-label',pieceNames[move.promotion]);}else b.textContent=move.path?move.path.map(m=>m.die).join(' + '):String(move.die);b.onclick=()=>{d.close();callback(move);};box.append(b);}d.showModal();}
