function chessClick(square){if(!canMove())return;const legal=legalMoves(state),options=legal.filter(m=>m.from===selected&&m.to===square);if(options.length){chooseMove(options,commitChessMove);return;}selected=selected===square?null:legal.some(m=>m.from===square)?square:null;renderBoard();renderControls();}
function nardsClick(point){if(!canMove())return;const legal=backgammonDestinations(state),options=legal.filter(m=>m.from===selected&&m.to===point);if(options.length){chooseMove(options,m=>send({type:'move',...m}));return;}selected=selected===point?null:legal.some(m=>m.from===point)?point:null;renderBoard();renderControls();}
