for(const b of document.querySelectorAll('[data-rank]'))b.onclick=()=>{rankKind=kind;rankMode=wager?'paid':'free';if(!$('ranking').open)$('ranking').showModal();loadRanking();};for(const b of document.querySelectorAll('[data-rank-kind]'))b.onclick=()=>{rankKind=b.dataset.rankKind;loadRanking();};for(const b of document.querySelectorAll('[data-rank-mode]'))b.onclick=()=>{rankMode=b.dataset.rankMode;loadRanking();};$('rankRetry').onclick=loadRanking;$('ranking').addEventListener('close',()=>rankGeneration++);
